(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-641":{scenario:{company:"Thien Ha Tower Operations",supervisor:{name:"Kiều Văn Thịnh",role:{vi:"Giám đốc Vận hành Tòa nhà",en:"Building Operations Director"}},ref_code:"WO-4417",title:{vi:"An toàn trước. Số liệu đúng. Hóa đơn minh bạch.",en:"Safety first. Right data. Transparent billing."},brief:{vi:"Bạn phụ trách vận hành tòa văn phòng Thiên Hà Tower. Báo cáo tuần WO-4417 có hai mục cần rà soát: phiếu sự cố “bơm chữa cháy chính không tự khởi động khi chạy thử tuần” và hóa đơn điện tháng 10 của khách thuê tầng 9. Công tơ của khách thuê đo gián tiếp qua biến dòng 200/5 A, chỉ số đầu kỳ 2418,6 và cuối kỳ 2571,8. Đối chiếu bản nháp với tài liệu gốc, sửa mức ưu tiên sự cố và sản lượng điện tính tiền (kWh), rồi lập báo cáo có căn cứ.",en:"You run operations at the Thien Ha Tower office building. Weekly report WO-4417 has two items to review: an incident ticket “main fire pump failed to auto-start during the weekly test” and the October electricity bill of the 9th-floor tenant. The tenant meter is CT-connected with a 200/5 A current transformer; the opening reading is 2418.6 and the closing reading is 2571.8. Compare the draft with the source documents, correct the incident priority and the billable energy (kWh), then write an evidence-based report."},reference_title:{vi:"Ma trận SLA & biên bản chốt chỉ số công tơ",en:"SLA matrix & meter reading record"},fields:[{id:"WO_PRIORITY",label:{vi:"Mức ưu tiên phiếu sự cố",en:"Incident ticket priority"},initial:"P3",expected:"P1",choices:["P1","P2","P3"],reference:"Ma trận ưu tiên sự cố (SLA)",ref_value:{vi:"P1: hệ thống an toàn sinh mạng (PCCC, thang máy kẹt người), phản hồi 15 phút; P2: ảnh hưởng khách thuê; P3: thường",en:"P1: life-safety systems (fire protection, trapped lift) - 15 min response; P2: tenant impact; P3: routine"},hint:{vi:"Bơm chữa cháy thuộc hệ thống an toàn sinh mạng, không phải hạng mục bảo trì thông thường.",en:"A fire pump is a life-safety system, not a routine maintenance item."}},{id:"BILL_KWH",label:{vi:"Sản lượng điện tính tiền (kWh)",en:"Billable energy (kWh)"},initial:"153.2",expected:"6128",reference:"Biên bản chốt chỉ số công tơ T10",ref_value:{vi:"Chỉ số đầu 2418,6; chỉ số cuối 2571,8; biến dòng 200/5 A; không có biến điện áp",en:"Opening 2418.6; closing 2571.8; CT 200/5 A; no voltage transformer"},hint:{vi:"Công tơ đo gián tiếp chỉ hiển thị phía thứ cấp, phải nhân với hệ số nhân của biến dòng.",en:"A CT-connected meter reads the secondary side, so multiply by the CT ratio."}}],sop32:{vi:"Sản lượng điện tính tiền = (chỉ số cuối - chỉ số đầu) x hệ số nhân công tơ; hệ số nhân = tỷ số biến dòng (sơ cấp/thứ cấp) x tỷ số biến điện áp (không có thì lấy 1). Đơn giá điện trong bài là số liệu mô phỏng.",en:"Billable energy = (closing - opening reading) x meter multiplier; multiplier = CT ratio (primary/secondary) x VT ratio (1 if none). Tariffs in this exercise are simulated figures."},context:{label:"BMS / CMMS · WO-4417",metrics:[{label:{vi:"Chỉ số đầu kỳ",en:"Opening reading"},value:"2418.6"},{label:{vi:"Chỉ số cuối kỳ",en:"Closing reading"},value:"2571.8"},{label:{vi:"Biến dòng",en:"Current transformer"},value:"200/5 A"},{label:{vi:"Đoàn kiểm tra PCCC (sáng mai)",en:"Fire inspection (tomorrow)"},value:"08:00"}]},crisis:{vi:"Đại diện chủ đầu tư nhắn: “Mai đoàn kiểm tra PCCC đến. Em cứ ký sổ bảo trì là bơm chữa cháy đạt, để bơm dự phòng chạy tay. Sửa bơm chính để quý sau cho đỡ chi phí.”",en:"The owner's representative messages you: “The fire inspectors come tomorrow. Just sign the maintenance log saying the fire pump passed and run the standby pump manually. Fix the main pump next quarter to save money.”"},options:{safe:{vi:"Ghi đúng tình trạng bơm, kích hoạt P1 gọi nhà thầu sửa ngay, bố trí trực PCCC tăng cường, báo Giám đốc tòa nhà bằng văn bản và trình bày trung thực với đoàn kiểm tra.",en:"Record the true pump status, raise a P1 call-out for immediate repair, add fire watch cover, inform the Building Director in writing and be honest with the inspectors."},shortcut:{vi:"Ký sổ bảo trì là đạt, cho bơm dự phòng chạy tay và để quý sau mới sửa bơm chính.",en:"Sign the log as passed, run the standby pump manually and fix the main pump next quarter."},wait:{vi:"Để nguyên phiếu P3 và chờ chủ đầu tư tự quyết định có sửa bơm hay không.",en:"Leave the ticket at P3 and wait for the owner to decide whether to repair the pump."}},questions:{vi:["Vì sao phiếu sự cố bơm chữa cháy phải là P1? Dẫn chứng từ ma trận SLA và rủi ro nếu để P3.","Trình bày cách tính 6128 kWh và cách bạn xử lý khiếu nại nếu khách thuê thắc mắc hóa đơn tăng mạnh."],en:["Why must the fire pump ticket be P1? Cite the SLA matrix and the risk of leaving it at P3.","Explain how you reached 6128 kWh and how you would handle the tenant's complaint about a much higher bill."]},hints:{vi:["Đặt phiếu sự cố cạnh ma trận SLA và xác định hệ thống bị ảnh hưởng thuộc nhóm nào.","Tìm tỷ số biến dòng trên biên bản chốt chỉ số trước khi áp dụng công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu ghi sai tình trạng thiết bị an toàn phải được từ chối và báo cáo."],en:["Place the ticket next to the SLA matrix and decide which system group is affected.","Find the CT ratio on the meter record before applying the formula in SOP 3.2.","Re-read SOP 4.2: any request to misreport safety equipment status must be refused and escalated."]}},learning:{summary:{vi:"Quản lý vận hành tòa nhà điều hành toàn bộ hệ thống kỹ thuật và dịch vụ của công trình: điện, điều hòa thông gió, cấp thoát nước, thang máy, PCCC, an ninh và vệ sinh. Người làm nghề lập kế hoạch bảo trì phòng ngừa, xử lý sự cố theo SLA, quản lý nhà thầu, kiểm soát năng lượng và chi phí dịch vụ, đồng thời bảo đảm tòa nhà an toàn, tuân thủ pháp luật và khách thuê hài lòng.",en:"A building and facility operations manager runs every technical system and service in a property: power, HVAC, plumbing, lifts, fire protection, security and cleaning. The role plans preventive maintenance, handles incidents to SLA, manages contractors, controls energy and service costs, and keeps the building safe, compliant and its tenants satisfied."},responsibilities:{vi:["Lập và giám sát kế hoạch bảo trì phòng ngừa cho hệ thống điện, HVAC, thang máy, PCCC và cấp thoát nước.","Tiếp nhận, phân loại ưu tiên và xử lý sự cố theo SLA, lưu vết trên hệ thống CMMS.","Quản lý nhà thầu dịch vụ: an ninh, vệ sinh, bảo trì chuyên ngành, nghiệm thu theo hợp đồng.","Theo dõi năng lượng, chốt chỉ số công tơ và lập hóa đơn điện nước, phí dịch vụ cho khách thuê.","Duy trì hồ sơ pháp lý PCCC, kiểm định thiết bị, diễn tập thoát nạn và báo cáo chủ đầu tư."],en:["Plan and supervise preventive maintenance for power, HVAC, lifts, fire protection and plumbing.","Receive, prioritize and resolve incidents to SLA, keeping an audit trail in the CMMS.","Manage service contractors for security, cleaning and specialist maintenance and accept work per contract.","Track energy, take meter readings and issue utility and service charge bills to tenants.","Keep fire safety records, equipment inspection certificates and evacuation drills current and report to the owner."]},competencies:[{name:{vi:"Kỹ thuật hệ thống tòa nhà",en:"Building systems engineering"},desc:{vi:"Hiểu nguyên lý điện hạ thế, chiller, AHU, bơm, thang máy và hệ thống BMS để chẩn đoán đúng sự cố.",en:"Understand low-voltage power, chillers, AHUs, pumps, lifts and the BMS well enough to diagnose faults."}},{name:{vi:"Quản lý bảo trì & SLA",en:"Maintenance & SLA management"},desc:{vi:"Xây dựng lịch bảo trì phòng ngừa, phân loại ưu tiên sự cố và đo thời gian phản hồi, khắc phục.",en:"Build preventive schedules, prioritize incidents and measure response and fix times."}},{name:{vi:"Quản lý năng lượng & chi phí",en:"Energy & cost control"},desc:{vi:"Đọc công tơ đo gián tiếp, phân bổ chi phí minh bạch và tìm giải pháp tiết kiệm năng lượng.",en:"Read CT-connected meters, allocate costs transparently and find energy savings."}},{name:{vi:"An toàn & tuân thủ",en:"Safety & compliance"},desc:{vi:"Giữ hệ thống PCCC, thang máy, thiết bị áp lực luôn sẵn sàng và đủ hồ sơ kiểm định, không ghi khống.",en:"Keep fire protection, lifts and pressure equipment ready with valid certificates and never falsify records."}},{name:{vi:"Dịch vụ khách thuê & nhà thầu",en:"Tenant & contractor service"},desc:{vi:"Giao tiếp rõ ràng với khách thuê, chủ đầu tư và nhà thầu; giải trình hóa đơn và sự cố bằng dữ liệu.",en:"Communicate clearly with tenants, owners and contractors and explain bills and incidents with data."}}],knowledge:{vi:["ISO 41001 về hệ thống quản lý cơ sở vật chất (Facility Management).","ISO 50001 về hệ thống quản lý năng lượng và nguyên tắc đo lường, giám sát tiêu thụ.","QCVN 06:2022/BXD về an toàn cháy cho nhà và công trình cùng quy định hiện hành về PCCC.","Nguyên lý đo đếm điện gián tiếp qua biến dòng, biến điện áp và cách tính hệ số nhân công tơ.","Quy định hiện hành về kiểm định kỹ thuật an toàn thang máy, thiết bị áp lực và an toàn lao động.","Nguyên tắc bảo trì phòng ngừa, bảo trì theo tình trạng và quản lý vòng đời tài sản."],en:["ISO 41001 for facility management systems.","ISO 50001 for energy management and the principles of metering and monitoring consumption.","QCVN 06:2022/BXD on fire safety of buildings and the current fire protection regulations.","CT and VT metering principles and how to calculate the meter multiplier.","Current rules on safety inspection of lifts, pressure equipment and occupational safety.","Preventive and condition-based maintenance and asset lifecycle management."]},tools:["Hệ thống quản lý tòa nhà BMS","Phần mềm quản lý bảo trì CMMS","Hệ thống báo cháy địa chỉ","Camera nhiệt và đồng hồ đo điện","Microsoft Excel / Power BI","Ứng dụng phản ánh của khách thuê"],kpis:{vi:["Tỷ lệ phiếu P1 được phản hồi trong 15 phút và khắc phục đúng hạn.","Tỷ lệ hoàn thành kế hoạch bảo trì phòng ngừa trong tháng.","Cường độ tiêu thụ năng lượng (kWh/m2/năm) so với kế hoạch.","Tỷ lệ hóa đơn khách thuê không phát sinh khiếu nại."],en:["Share of P1 tickets answered within 15 minutes and fixed on time.","Monthly preventive maintenance completion rate.","Energy use intensity (kWh/m2/year) against plan.","Share of tenant bills issued without complaints."]},day:[{time:"07:30",vi:"Đi tuần kỹ thuật, xem cảnh báo BMS và nhật ký trực đêm.",en:"Walk the plant rooms, review BMS alarms and the night shift log."},{time:"09:00",vi:"Họp giao ban với đội kỹ thuật, an ninh, vệ sinh và phân công phiếu công việc.",en:"Brief the technical, security and cleaning teams and assign work orders."},{time:"11:00",vi:"Giám sát chạy thử tuần bơm chữa cháy và máy phát điện dự phòng.",en:"Witness the weekly fire pump and standby generator tests."},{time:"14:00",vi:"Chốt chỉ số công tơ, đối chiếu hệ số nhân và lập hóa đơn khách thuê.",en:"Take meter readings, check multipliers and prepare tenant bills."},{time:"16:30",vi:"Làm việc với nhà thầu, cập nhật CMMS và báo cáo chủ đầu tư.",en:"Meet contractors, update the CMMS and report to the owner."}],mistakes:{vi:["Xếp sự cố hệ thống an toàn sinh mạng vào mức ưu tiên thông thường.","Quên nhân hệ số biến dòng khi tính điện cho công tơ đo gián tiếp.","Ký biên bản bảo trì “đạt” khi thiết bị chưa được kiểm tra thực tế."],en:["Treating a life-safety system fault as a routine priority.","Forgetting the CT multiplier when billing a CT-connected meter.","Signing a maintenance record as passed without actually testing the equipment."]},career:[{vi:"Kỹ thuật viên vận hành tòa nhà",en:"Building operations technician"},{vi:"Trưởng ca kỹ thuật / Giám sát kỹ thuật",en:"Shift lead / Technical supervisor"},{vi:"Quản lý vận hành tòa nhà",en:"Building operations manager"},{vi:"Giám đốc quản lý bất động sản & cơ sở vật chất",en:"Head of property & facility management"}],glossary:[{term:"BMS",vi:"Hệ thống quản lý tòa nhà giám sát, điều khiển tập trung HVAC, điện, bơm và cảnh báo.",en:"Building management system that centrally monitors and controls HVAC, power, pumps and alarms."},{term:"CMMS",vi:"Phần mềm quản lý bảo trì lưu phiếu công việc, lịch bảo trì, vật tư và lịch sử thiết bị.",en:"Maintenance software holding work orders, schedules, spares and equipment history."},{term:"SLA",vi:"Cam kết mức dịch vụ: thời gian phản hồi và khắc phục theo từng mức ưu tiên.",en:"Service level agreement setting response and fix times for each priority."},{term:"Biến dòng (CT)",vi:"Thiết bị hạ dòng điện lớn xuống mức đo được; công tơ đo qua CT phải nhân hệ số nhân.",en:"Current transformer that steps current down for metering; readings must be multiplied by its ratio."},{term:"PPM",vi:"Bảo trì phòng ngừa theo kế hoạch, thực hiện định kỳ trước khi thiết bị hỏng.",en:"Planned preventive maintenance carried out periodically before equipment fails."}],quiz:[{q:{vi:"Công tơ qua biến dòng 300/5 A, chỉ số tăng 120,0 trong tháng. Sản lượng tính tiền là bao nhiêu?",en:"A meter on a 300/5 A CT advances 120.0 in a month. What is the billable energy?"},options:{vi:["120 kWh","600 kWh","7200 kWh","36000 kWh"],en:["120 kWh","600 kWh","7200 kWh","36000 kWh"]},answer:2,explain:{vi:"Hệ số nhân = 300/5 = 60; sản lượng = 120 x 60 = 7200 kWh.",en:"Multiplier = 300/5 = 60; energy = 120 x 60 = 7200 kWh."}},{q:{vi:"Sự cố nào phải xếp mức ưu tiên cao nhất?",en:"Which incident must get the highest priority?"},options:{vi:["Thang máy kẹt người","Bóng đèn hành lang hỏng","Vòi nước nhà vệ sinh rỉ","Thảm sảnh bị bẩn"],en:["A lift with people trapped","A broken corridor lamp","A dripping restroom tap","A dirty lobby carpet"]},answer:0,explain:{vi:"Sự cố đe dọa an toàn sinh mạng luôn là P1, phải phản hồi ngay.",en:"Anything threatening life safety is always P1 and needs an immediate response."}},{q:{vi:"Chủ đầu tư yêu cầu ký biên bản bơm chữa cháy “đạt” dù bơm đang lỗi. Bạn làm gì?",en:"The owner asks you to sign the fire pump as passed although it is faulty. What do you do?"},options:{vi:["Ký cho kịp đoàn kiểm tra","Ghi đúng tình trạng, sửa khẩn và báo cáo bằng văn bản","Ký nhưng ghi chú miệng với đội kỹ thuật","Không làm gì chờ chủ đầu tư"],en:["Sign it before the inspection","Record the true status, repair urgently and report in writing","Sign it and tell the team verbally","Do nothing and wait for the owner"]},answer:1,explain:{vi:"Ghi khống hồ sơ PCCC là vi phạm và đe dọa sinh mạng; phải trung thực, khắc phục và báo cáo.",en:"Falsifying fire records is a violation that endangers lives; be truthful, fix it and escalate."}},{q:{vi:"Tiêu chuẩn quốc tế nào dành cho hệ thống quản lý cơ sở vật chất?",en:"Which international standard covers facility management systems?"},options:{vi:["ISO 9001","ISO 27001","ISO 14001","ISO 41001"],en:["ISO 9001","ISO 27001","ISO 14001","ISO 41001"]},answer:3,explain:{vi:"ISO 41001 quy định yêu cầu cho hệ thống quản lý cơ sở vật chất (FM).",en:"ISO 41001 sets requirements for facility management systems."}}],tools_en:["Building management system (BMS)","CMMS maintenance management software","Addressable fire alarm system","Thermal camera and electrical meters","Microsoft Excel / Power BI","Tenant feedback app"]}}})})(window.KKR);
